// --- ArenaFrame usage ---
//
// install / Rf_install / create_symbol do NOT use arena memory.
// Symbol nodes are heap-allocated (std::malloc) and stored in gSymbolCache
// for the thread lifetime.  They must NOT be freed by ArenaFrame at the
// .Call boundary because their pointer values are used as _frame_registry
// keys across multiple init_rpcallback_wrapper invocations.
//
// The .Call boundary wrapper for init_rpcallback must still declare:
//   ArenaFrame _frame;
// as its first statement, because rpart_callback1/2 (compiled in the same
// translation unit) use R_alloc / ALLOC (arena-backed).  See R_getVar.h
// for the full init_rpcallback_wrapper template.

#endif // FAKE_R_INSTALL_H
